import { cn } from "@/lib/utils";
import { ECONOMY_ICONS, type EconomyIconName } from "./economy-icons.generated";

export type { EconomyIconName };

/**
 * A single warm-duotone economy icon, sliced from the shared sprite sheet
 * (generated by web/scripts/economy-icons). Shares the exact STYLE of the
 * housing icon set, so both read on the warm-white and terminal-black themes.
 *
 * @param name  icon id from the manifest (autocompleted)
 * @param size  rendered px (square); the sprite cell is downscaled to this
 */
export function EconomyIcon({
  name,
  size = 16,
  className,
  title,
}: {
  name: EconomyIconName;
  size?: number;
  className?: string;
  title?: string;
}) {
  const pos = ECONOMY_ICONS.icons[name];
  if (!pos) return null;
  const scale = size / ECONOMY_ICONS.cell;
  // Icons always sit beside their text label, so they're decorative by default
  // (aria-hidden). Pass `title` only for a genuinely standalone, label-less icon.
  const a11y = title ? { role: "img", "aria-label": title } : { "aria-hidden": true };
  return (
    <span
      {...a11y}
      className={cn("inline-block shrink-0 align-[-0.15em]", className)}
      style={{
        width: size,
        height: size,
        backgroundImage: `url(${ECONOMY_ICONS.sheet})`,
        backgroundRepeat: "no-repeat",
        backgroundSize: `${ECONOMY_ICONS.width * scale}px ${ECONOMY_ICONS.height * scale}px`,
        backgroundPosition: `-${pos.x * scale}px -${pos.y * scale}px`,
      }}
    />
  );
}
